create table private.zoom_invites (id uuid primary key default gen_random_uuid(), slot_id uuid not null references public.zoom_agent_slots(id) on delete cascade, code_hash text not null, state text not null default 'active' check(state in ('active','claiming','used','revoked')), claim_token uuid, claim_started_at timestamptz, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), used_at timestamptz, used_by uuid references auth.users(id) on delete set null, revoked_at timestamptz);
create unique index zoom_one_active_invite_per_slot on private.zoom_invites(slot_id) where state in ('active','claiming');
create index zoom_invites_state_idx on private.zoom_invites(state, slot_id);
create or replace function private.zoom_reserve_invite(requested_initials text, requested_hash text, token uuid) returns table(invite_id uuid, reserved_slot_id uuid) language plpgsql security definer set search_path=public,private,pg_catalog as $$ begin
 return query with candidate as (select i.id,i.slot_id from private.zoom_invites i join public.zoom_agent_slots s on s.id=i.slot_id where s.initials=upper(trim(requested_initials)) and s.status='pending' and i.state='active' and i.code_hash=requested_hash for update of i) update private.zoom_invites i set state='claiming',claim_token=token,claim_started_at=now() from candidate c where i.id=c.id returning i.id,i.slot_id; end $$;
create or replace function private.zoom_finalize_invite(invite uuid, token uuid, account uuid) returns boolean language plpgsql security definer set search_path=public,private,pg_catalog as $$ declare sid uuid; begin update private.zoom_invites set state='used',used_at=now(),used_by=account where id=invite and state='claiming' and claim_token=token returning slot_id into sid; if sid is null then return false; end if; update public.zoom_agent_slots set status='claimed',claimed_by=account,updated_at=now() where id=sid; return true; end $$;
create or replace function private.zoom_release_invite(invite uuid, token uuid) returns boolean language sql security definer set search_path=public,private,pg_catalog as $$ update private.zoom_invites set state='active',claim_token=null,claim_started_at=null where id=invite and state='claiming' and claim_token=token returning true; $$;
revoke all on function private.zoom_reserve_invite(text,text,uuid),private.zoom_finalize_invite(uuid,uuid,uuid),private.zoom_release_invite(uuid,uuid) from public;
